php=r'''<?php
/** Reports, live moderation, copyright/takedown and appeal history. */
defined( 'ABSPATH' ) || exit;
final class VWLB_Moderation {
	public static function report($data){if(!is_user_logged_in())return VWLB_Helpers::error('vwlb_login_required',__('Sign in to report content.',VWLB_TEXT_DOMAIN),401);$rate=VWLB_Security::rate_limit('media_report',10,HOUR_IN_SECONDS);if(is_wp_error($rate))return $rate;$target_type=VWLB_Helpers::enum($data['target_type']??'',array('video','live','caption','chat'),'');$target_id=absint($data['target_id']??0);$reason=VWLB_Helpers::text($data['reason']??'',191);if(!$target_type||!$target_id||!$reason)return VWLB_Helpers::error('vwlb_report_invalid',__('Target and reason are required.',VWLB_TEXT_DOMAIN));global $wpdb;$now=VWLB_Helpers::now();$saved=$wpdb->insert(VWLB_Helpers::table('moderation'),array('public_id'=>VWLB_Helpers::public_id('mod'),'target_type'=>$target_type,'target_id'=>$target_id,'reason'=>$reason,'action'=>'reported','status'=>'open','severity'=>VWLB_Helpers::enum($data['severity']??'medium',array('low','medium','high','critical'),'medium'),'note'=>VWLB_Helpers::textarea($data['note']??'',10000),'evidence_json'=>VWLB_Helpers::json_encode($data['evidence']??array()),'reporter_id'=>get_current_user_id(),'created_at'=>$now,'updated_at'=>$now));if(!$saved||!(int)$wpdb->insert_id)return VWLB_Helpers::error('vwlb_database_error',__('Moderation report could not be saved.',VWLB_TEXT_DOMAIN),500);$id=(int)$wpdb->insert_id;VWLB_Helpers::audit('moderation',$id,'report','','open',$reason);do_action('vwlb_moderation_reported',$id,$data);return array('id'=>$id,'status'=>'open');}
	public static function decide($report_id,$action,$note){$report=VWLB_Repository::find('moderation',$report_id);if(!$report)return VWLB_Helpers::error('vwlb_report_missing',__('Report not found.',VWLB_TEXT_DOMAIN),404);if(!VWLB_Security::can(VWLB_Contracts::CAP_MODERATE,null,'moderation_decision'))return VWLB_Helpers::error('vwlb_forbidden',__('You cannot moderate media.',VWLB_TEXT_DOMAIN),403);$action=VWLB_Helpers::enum($action,array('dismiss','restrict','remove','block','slow_mode','restore','escalate'),'');if(!$action||!trim($note))return VWLB_Helpers::error('vwlb_moderation_note_required',__('A decision and reason are required.',VWLB_TEXT_DOMAIN),422);return VWLB_DB::transaction(function()use($report,$action,$note){global $wpdb;$fresh=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.VWLB_Helpers::table('moderation').' WHERE id=%d FOR UPDATE',$report['id']),ARRAY_A);if(!$fresh||!in_array($fresh['status'],array('open','escalated'),true))return VWLB_Helpers::error('vwlb_moderation_conflict',__('This report is no longer open for this decision.',VWLB_TEXT_DOMAIN),409);$status=in_array($action,array('dismiss','restrict','remove','block','restore'),true)?'closed':'escalated';if('live'===$fresh['target_type']&&'slow_mode'===$action){$live=VWLB_Repository::find('live_events',$fresh['target_id'],true);if(!$live)return VWLB_Helpers::error('vwlb_target_missing',__('Moderation target no longer exists.',VWLB_TEXT_DOMAIN),404);$changed=VWLB_Repository::update_versioned('live_events',$live['id'],$live['version'],array('slow_mode_seconds'=>(int)apply_filters('vwlb_moderation_slow_mode_seconds',30,$fresh)));if(is_wp_error($changed))return $changed;}if(in_array($fresh['target_type'],array('video','live'),true)&&in_array($action,array('restrict','remove','restore'),true)){$entity='video'===$fresh['target_type']?'videos':'live_events';$row=VWLB_Repository::find($entity,$fresh['target_id'],true);if(!$row)return VWLB_Helpers::error('vwlb_target_missing',__('Moderation target no longer exists.',VWLB_TEXT_DOMAIN),404);$new='restore'===$action?('video'===$fresh['target_type']?'published':'scheduled'):('remove'===$action?'removed':'restricted');$changed=VWLB_Repository::update_versioned($entity,$row['id'],$row['version'],array('status'=>$new));if(is_wp_error($changed))return $changed;VWLB_Helpers::outbox(ucfirst($fresh['target_type']).ucfirst($new),$fresh['target_type'],$row['id'],array('reason_category'=>$fresh['reason']));}$changed=$wpdb->update(VWLB_Helpers::table('moderation'),array('action'=>$action,'status'=>$status,'note'=>VWLB_Helpers::textarea($note,10000),'reviewer_id'=>get_current_user_id(),'updated_at'=>VWLB_Helpers::now(),'closed_at'=>'closed'===$status?VWLB_Helpers::now():null),array('id'=>$fresh['id'],'status'=>$fresh['status']));if(1!==$changed)return VWLB_Helpers::error('vwlb_moderation_conflict',__('Moderation report changed concurrently.',VWLB_TEXT_DOMAIN),409);if(in_array($fresh['target_type'],array('chat','live'),true)&&in_array($action,array('block','slow_mode'),true))do_action('vwlb_live_chat_moderation',$action,$fresh);VWLB_Helpers::audit('moderation',$fresh['id'],'decide',$fresh['status'],$status,$note,array('action'=>$action));return array('id'=>$fresh['id'],'status'=>$status,'action'=>$action);});}
	public static function file_takedown($data){$rate=VWLB_Security::rate_limit('takedown',5,DAY_IN_SECONDS);if(is_wp_error($rate))return $rate;$target_type=VWLB_Helpers::enum($data['target_type']??'',array('video','live'),'');$target_id=absint($data['target_id']??0);$basis=VWLB_Helpers::text($data['rights_basis']??'',191);if(!$target_type||!$target_id||!$basis)return VWLB_Helpers::error('vwlb_takedown_invalid',__('Target and rights basis are required.',VWLB_TEXT_DOMAIN));global $wpdb;$now=VWLB_Helpers::now();$saved=$wpdb->insert(VWLB_Helpers::table('takedowns'),array('public_id'=>VWLB_Helpers::public_id('td'),'target_type'=>$target_type,'target_id'=>$target_id,'claimant_id'=>get_current_user_id(),'claimant_contact_hash'=>hash_hmac('sha256',sanitize_email($data['contact']??''),wp_salt('auth')),'rights_basis'=>$basis,'evidence_json'=>VWLB_Helpers::json_encode($data['evidence']??array()),'status'=>'reported','created_at'=>$now,'updated_at'=>$now));if(!$saved||!(int)$wpdb->insert_id)return VWLB_Helpers::error('vwlb_database_error',__('Takedown report could not be saved.',VWLB_TEXT_DOMAIN),500);$id=(int)$wpdb->insert_id;VWLB_Helpers::audit('takedown',$id,'file','','reported',$basis);do_action('vwlb_takedown_filed',$id,$data);return array('id'=>$id,'status'=>'reported');}
	public static function transition_takedown($id,$to,$expected_version,$reason){$case=VWLB_Repository::find('takedowns',$id);if(!$case)return VWLB_Helpers::error('vwlb_takedown_missing',__('Takedown case not found.',VWLB_TEXT_DOMAIN),404);$owner=(int)$case['claimant_id']===get_current_user_id();$moderator=VWLB_Security::can(VWLB_Contracts::CAP_MODERATE,null,'takedown_decision');$to=VWLB_Helpers::enum($to,VWLB_Contracts::TAKEDOWN_STATES,'');if($owner&&!$moderator&&!in_array($to,array('appealed','closed'),true))return VWLB_Helpers::error('vwlb_takedown_decision_forbidden',__('Claimants may appeal or close their own case, but cannot issue moderation decisions.',VWLB_TEXT_DOMAIN),403);if(!$owner&&!$moderator)return VWLB_Helpers::error('vwlb_forbidden',__('You cannot update this case.',VWLB_TEXT_DOMAIN),403);$assert=VWLB_State_Machine::assert('takedown',$case['status'],$to);if(is_wp_error($assert))return $assert;if(!$reason)return VWLB_Helpers::error('vwlb_reason_required',__('A reason is required.',VWLB_TEXT_DOMAIN),422);return VWLB_DB::transaction(function()use($case,$to,$expected_version,$reason,$moderator){$fresh=VWLB_Repository::find('takedowns',$case['id'],true);if(!$fresh||(int)$fresh['version']!==(int)$expected_version)return VWLB_Helpers::error('vwlb_version_conflict',__('Takedown case changed. Refresh and try again.',VWLB_TEXT_DOMAIN),409);if(in_array($to,array('restricted','removed','restored'),true)){$entity='video'===$fresh['target_type']?'videos':'live_events';$target=VWLB_Repository::find($entity,$fresh['target_id'],true);if(!$target)return VWLB_Helpers::error('vwlb_target_missing',__('Copyright target no longer exists.',VWLB_TEXT_DOMAIN),404);$status='restored'===$to?('videos'===$entity?'published':'scheduled'):('removed'===$to?'removed':'restricted');$changed=VWLB_Repository::update_versioned($entity,$target['id'],$target['version'],array('status'=>$status));if(is_wp_error($changed))return $changed;VWLB_Helpers::outbox('Copyright'.ucfirst($to),$fresh['target_type'],$target['id'],array('case_public_id'=>$fresh['public_id']));}$updated=VWLB_Repository::update_versioned('takedowns',$fresh['id'],$fresh['version'],array('status'=>$to,'decision_reason'=>VWLB_Helpers::textarea($reason,10000),'reviewer_id'=>$moderator?get_current_user_id():0,'closed_at'=>in_array($to,array('removed','restored','closed'),true)?VWLB_Helpers::now():null));if(is_wp_error($updated))return $updated;VWLB_Helpers::audit('takedown',$fresh['id'],'transition',$fresh['status'],$to,$reason);return $updated;});}
}
'''
p.write_text(php)
r=reg.read_text()
marker="""# R23 — moderation decisions are atomic and takedown claimants cannot self-issue restrict/remove/restore decisions.\nneed \"Moderation report could not be saved\" \"$P/includes/class-vwlb-moderation.php\" r23-report-db\nneed \"Takedown report could not be saved\" \"$P/includes/class-vwlb-moderation.php\" r23-takedown-db\nneed \"FOR UPDATE\" \"$P/includes/class-vwlb-moderation.php\" r23-lock\nneed \"vwlb_takedown_decision_forbidden\" \"$P/includes/class-vwlb-moderation.php\" r23-claimant-authority\nneed \"VWLB_DB::transaction\" \"$P/includes/class-vwlb-moderation.php\" r23-atomicity\n"""
